import React, { useState } from "react";
import axios from "axios";

import {
  Box,
  Button,
  TextField,
  Typography,
  Paper,
  Tabs,
  Tab,
  InputAdornment,
  IconButton,
  Alert,
  MenuItem,
} from "@mui/material";

import {
  Visibility,
  VisibilityOff,
  Restaurant,
} from "@mui/icons-material";


const AuthPage = ({ onLogin }) => {

  // =====================================================
  // STATE
  // =====================================================

  const [mode, setMode] = useState(0); // 0 = Login, 1 = Register

  const [role, setRole] = useState("user");

  const [loginData, setLoginData] = useState({
    mobile: "",
    password: "",
  });

  const [registerData, setRegisterData] = useState({
    name: "",
    mobile: "",
    password: "",
  });

  const [showLoginPassword, setShowLoginPassword] = useState(false);
  const [showRegisterPassword, setShowRegisterPassword] = useState(false);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");


  // =====================================================
  // ROLE NAME
  // =====================================================

  const getRoleName = () => {
    if (role === "user") return "User";
    if (role === "staff") return "Staff";
    if (role === "admin") return "Admin";

    return "User";
  };


  // =====================================================
  // LOGIN
  // =====================================================

  const handleLogin = async (e) => {
    e.preventDefault();

    setError("");
    setSuccess("");
    setLoading(true);

    try {

      const response = await axios.post(
        "/api/auth/login",
        {
          mobile: loginData.mobile,
          password: loginData.password,
          role: role,
        }
      );

      const { token, user } = response.data;

      // Save login information
      localStorage.setItem("token", token);
      localStorage.setItem("user", JSON.stringify(user));

      // Set axios authorization
      axios.defaults.headers.common["Authorization"] =
        `Bearer ${token}`;

      setSuccess("Login successful");

      // Send user to App.js
      onLogin(user);

    } catch (error) {

      setError(
        error.response?.data?.message ||
        "Login failed. Please try again."
      );

    } finally {
      setLoading(false);
    }
  };


  // =====================================================
  // REGISTER
  // =====================================================

  const handleRegister = async (e) => {
    e.preventDefault();

    setError("");
    setSuccess("");
    setLoading(true);

    try {

      const response = await axios.post(
        "/api/auth/register",
        {
          name: registerData.name,
          mobile: registerData.mobile,
          password: registerData.password,
          role: role,
        }
      );

      setSuccess(
        response.data.message || "Registration successful"
      );

      // Clear registration form
      setRegisterData({
        name: "",
        mobile: "",
        password: "",
      });

      // Go to Login
      setMode(0);

    } catch (error) {

      setError(
        error.response?.data?.message ||
        "Registration failed. Please try again."
      );

    } finally {
      setLoading(false);
    }
  };


  // =====================================================
  // ROLE CHANGE
  // =====================================================

  const handleRoleChange = (event) => {

    setRole(event.target.value);

    setError("");
    setSuccess("");

    setLoginData({
      mobile: "",
      password: "",
    });

    setRegisterData({
      name: "",
      mobile: "",
      password: "",
    });
  };


  // =====================================================
  // UI
  // =====================================================

  return (

    <Box
      sx={{
        minHeight: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        background:
          "linear-gradient(135deg, #f5f7fa 0%, #e4ecf7 100%)",
        padding: 2,
      }}
    >

      <Paper
        elevation={8}
        sx={{
          width: "100%",
          maxWidth: 450,
          borderRadius: 4,
          overflow: "hidden",
        }}
      >

        {/* =================================================
            HEADER
        ================================================= */}

        <Box
          sx={{
            background: "#1976d2",
            color: "white",
            padding: 4,
            textAlign: "center",
          }}
        >

          <Restaurant
            sx={{
              fontSize: 45,
              marginBottom: 1,
            }}
          />

          <Typography
            variant="h4"
            fontWeight="bold"
          >
            CanteenPro
          </Typography>

          <Typography
            variant="body2"
            sx={{ opacity: 0.9, mt: 1 }}
          >
            {getRoleName()} Portal
          </Typography>

        </Box>


        {/* =================================================
            ROLE SELECTOR
        ================================================= */}

        <Box sx={{ padding: 3, pb: 1 }}>

          <Typography
            variant="subtitle1"
            fontWeight="bold"
            sx={{ mb: 1 }}
          >
            Select Role
          </Typography>

          <TextField
            select
            fullWidth
            value={role}
            onChange={handleRoleChange}
          >

            <MenuItem value="user">
              User
            </MenuItem>

            <MenuItem value="staff">
              Staff
            </MenuItem>

            <MenuItem value="admin">
              Admin
            </MenuItem>

          </TextField>

        </Box>


        {/* =================================================
            LOGIN / REGISTER TABS
        ================================================= */}

        <Tabs
          value={mode}
          onChange={(e, value) => {
            setMode(value);
            setError("");
            setSuccess("");
          }}
          centered
          variant="fullWidth"
        >

          <Tab label="Login" />

          <Tab label="Register" />

        </Tabs>


        <Box sx={{ padding: 3 }}>

          {/* ALERTS */}

          {error && (
            <Alert
              severity="error"
              sx={{ mb: 2 }}
            >
              {error}
            </Alert>
          )}

          {success && (
            <Alert
              severity="success"
              sx={{ mb: 2 }}
            >
              {success}
            </Alert>
          )}


          {/* =================================================
              LOGIN FORM
          ================================================= */}

          {mode === 0 && (

            <Box
              component="form"
              onSubmit={handleLogin}
            >

              <Typography
                variant="h6"
                fontWeight="bold"
                sx={{ mb: 2 }}
              >
                {getRoleName()} Login
              </Typography>


              <TextField
                fullWidth
                label="Mobile Number"
                value={loginData.mobile}
                onChange={(e) =>
                  setLoginData({
                    ...loginData,
                    mobile: e.target.value,
                  })
                }
                inputProps={{
                  maxLength: 10,
                }}
                sx={{ mb: 2 }}
                required
              />


              <TextField
                fullWidth
                label="Password"
                type={
                  showLoginPassword
                    ? "text"
                    : "password"
                }
                value={loginData.password}
                onChange={(e) =>
                  setLoginData({
                    ...loginData,
                    password: e.target.value,
                  })
                }
                required
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">

                      <IconButton
                        onClick={() =>
                          setShowLoginPassword(
                            !showLoginPassword
                          )
                        }
                        edge="end"
                      >

                        {showLoginPassword ? (
                          <VisibilityOff />
                        ) : (
                          <Visibility />
                        )}

                      </IconButton>

                    </InputAdornment>
                  ),
                }}
                sx={{ mb: 3 }}
              />


              <Button
                type="submit"
                fullWidth
                variant="contained"
                size="large"
                disabled={loading}
              >
                {loading
                  ? "Logging in..."
                  : `Login as ${getRoleName()}`}
              </Button>

            </Box>
          )}


          {/* =================================================
              REGISTER FORM
          ================================================= */}

          {mode === 1 && (

            <Box
              component="form"
              onSubmit={handleRegister}
            >

              <Typography
                variant="h6"
                fontWeight="bold"
                sx={{ mb: 2 }}
              >
                {getRoleName()} Registration
              </Typography>


              <TextField
                fullWidth
                label="Full Name"
                value={registerData.name}
                onChange={(e) =>
                  setRegisterData({
                    ...registerData,
                    name: e.target.value,
                  })
                }
                required
                sx={{ mb: 2 }}
              />


              <TextField
                fullWidth
                label="Mobile Number"
                value={registerData.mobile}
                onChange={(e) =>
                  setRegisterData({
                    ...registerData,
                    mobile: e.target.value,
                  })
                }
                inputProps={{
                  maxLength: 10,
                }}
                required
                sx={{ mb: 2 }}
              />


              <TextField
                fullWidth
                label="Password"
                type={
                  showRegisterPassword
                    ? "text"
                    : "password"
                }
                value={registerData.password}
                onChange={(e) =>
                  setRegisterData({
                    ...registerData,
                    password: e.target.value,
                  })
                }
                required
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">

                      <IconButton
                        onClick={() =>
                          setShowRegisterPassword(
                            !showRegisterPassword
                          )
                        }
                        edge="end"
                      >

                        {showRegisterPassword ? (
                          <VisibilityOff />
                        ) : (
                          <Visibility />
                        )}

                      </IconButton>

                    </InputAdornment>
                  ),
                }}
                sx={{ mb: 3 }}
              />


              <Button
                type="submit"
                fullWidth
                variant="contained"
                size="large"
                disabled={loading}
              >
                {loading
                  ? "Creating account..."
                  : `Register as ${getRoleName()}`}
              </Button>

            </Box>
          )}

        </Box>

